import { p } from './content.js';
import { browserDemo as demo, lesson, mdnSource as mdn } from './lesson-example.js';

const element = tag => mdn('<' + tag + '>', 'Web/HTML/Reference/Elements/' + tag);
const resolvedPaths = '<p id="paths" style="white-space: pre-wrap; overflow-wrap: anywhere"></p>';
const resolvePaths = base => ({
  script: [
    'const pageURL = ' + JSON.stringify(base) + ';',
    'const examples = [...document.querySelectorAll("#examples a")];',
    'document.querySelector("#paths").textContent = examples.map(link => {',
    '  const path = link.getAttribute("href");',
    '  return path + " → " + new URL(path, pageURL).href;',
    '}).join("\\n");',
  ].join('\n'),
});

